using System.Drawing;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    private StatusStrip _statusStrip;

    public MyControl()
    {
        _statusStrip = new StatusStrip();
        // .NET 9 breaking change: ToolStrip/StatusStrip default RenderMode changed
        // from ManagerRenderMode to System. Explicitly set to preserve .NET 8 visuals.
        _statusStrip.RenderMode = ToolStripRenderMode.ManagerRenderMode;
        _statusStrip.Items.Add(new ToolStripStatusLabel("Ready"));
        Controls.Add(_statusStrip);
    }

    // .NET 9 breaking change: IWindowsFormsEditorService.DropDownControl now throws
    // ArgumentNullException when passed null. Guard against null before calling.
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (editorService is null)
            throw new ArgumentNullException(nameof(editorService));
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }

    // .NET 9: LibraryImport (source-generated) is preferred over DllImport for P/Invoke.
    // COM interop via ComWrappers is now the recommended pattern.
    [LibraryImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static partial bool IsWindowVisible(IntPtr hWnd);

    [LibraryImport("user32.dll", SetLastError = true)]
    private static partial IntPtr GetForegroundWindow();

    public bool IsCurrentWindowVisible()
    {
        IntPtr hwnd = GetForegroundWindow();
        return IsWindowVisible(hwnd);
    }
}

